udge ? { content: [...(Array.isArray(e.content) ? e.content : []), { type: \\\"text\\\", text: `<system-reminder>\\\\n${nudge}\\\\n</system-reminder>` }] } : undefined;\\n  });\\n  register(\\\"turn_end\\\", (_e: any, ctx: any) => {\\n    const nudge = manager.observeTurn();\\n    updateBudgetWidget(ctx);\\n    curator.idle();\\n    return nudge ? { message: nudge } : undefined;\\n  });\\n  register(\\\"session_start\\\", (_e: any, ctx: any) => {\\n    // getEntries() includes the whole session tree and can resurrect state\\n    // from a sibling branch. Only the active branch is authoritative.\\n    const branch = ctx.sessionManager?.getBranch?.();\\n    manager.rehydrate(Array.isArray(branch) ? branch : []);\\n    updateBudgetWidget(ctx);\\n    installFooter(ctx);\\n    curator.idle();\\n  });\\n  register(\\\"session_shutdown\\\", () => curator.dispose());\\n  pi.registerTool({ name: \\\"Skill\\\", label: \\\"Invoke skill\\\", description: \\\"Invoke a matching reusable skill before performing the task. The skill instructions are returned for you to follow.\\\", parameters: skillSchema, async execute(_id: string, params: any) {\\n    try {\\n      const args = params.args ?? \\\"\\\";\\n      const invoked = manager.config.skillInvoker ? manager.config.skillInvoker(params.skill, args) : manager.invokeSkill(params.skill, args);\\n      const result = invoked instanceof Promise ? await invoked : invoked;\\n      if (manager.config.skillInvoker) manager.recordSkillInvocation(params.skill, result.version ?? \\\"unknown\\\");\\n      return { content: [{ type: \\\"text\\\", text: JSON.stringify(result) }], details: {} }; }\\n    catch (e) {\\n      const message = e instanceof Error ? e.message : String(e);\\n      return { content: [{ type: \\\"text\\\", text: JSON.stringify({ error: message }) }], isError: true, details: { code: \\\"skill_not_found\\\", message } };\\n    }\\n  } });\\n  pi.registerTool({ name: \\\"SkillManage\\\", label: \\\"Manage autogenerated skills\\\", description: \\\"Create, review, patch, inspect, and archive reusable autogenerated skill packages. Prefer patching an existing umbrella; never overwrite skills.\\\", parameters: skillManageSchema, async execute(_id: string, params: any) { try { return { content: [{ type: \\\"text\\\", text: JSON.stringify(manager.execute(params)) }], details: {} }; } catch (e) { return { content: [{ type: \\\"text\\\", text: JSON.stringify({ error: e instanceof Error ? e.message : String(e) }) }], isError: true, details: {} }; } } });\\n  pi.registerCommand?.(\\\"curator\\\", {\\n    description: \\\"Preview or apply autogenerated-skill curator maintenance\\\",\\n    handler: async (args: string, ctx: any) => {\\n      const words = args.trim().split(/\\\\s+/).filter(Boolean);\\n      const action = words[0] || \\\"preview\\\";\\n      if (action !== \\\"preview\\\" && action !== \\\"apply\\\") {\\n        ctx.ui?.notify?.(\\\"Usage: /curator preview|apply [--consolidate]\\\", \\\"error\\\");\\n        return;\\n      }\\n      try {\\n        const result = await curator.run({ preview: action === \\\"preview\\\", consolidate: words.includes(\\\"--consolidate\\\") });\\n        ctx.ui?.notify?.(result.output || JSON.stringify(result), \\\"info\\\");\\n      } catch (error) {\\n        ctx.ui?.notify?.(`Curator failed: ${error instanceof Error ? error.message : String(error)}`, \\\"error\\\");\\n      }\\n    },\\n  });\\n  autogenByPi.set(owner, manager);\\n  return manager;\\n}\\n\",\"skills/test/loader.test.ts\":\"import { describe, expect, it } from \\\"vitest\\\";\\nimport { mkdirSync, mkdtempSync, writeFileSync } from \\\"node:fs\\\";\\nimport { join } from \\\"node:path\\\";\\nimport { tmpdir } from \\\"node:os\\\";\\nimport { generateAvailableSkillsXML, SkillLoader } from \\\"../src/index.js\\\";\\nconst skill=(root:string,name:string,body:string)=>{const d=join(root,name);mkdirSync(d,{recursive:true});writeFileSync(join(d,\\\"SKILL.md\\\"),`---\\\\nname: ${name}\\\\ndescription: ${name} skill\\\\n---\\\\n${body}`);return d};\\ndescribe(\\\"Swarm skill loader\\\",()=>{\\n it(\\\"uses managed precedence and discovers packages/support files\\\",()=>{const root=mkdtempSync(join(tmpdir(),\\\"skills-\\\")),managed=join(root,\\\"managed\\\"),project=join(root,\\\"project\\\"),projectSkills=join(project,\\\".swarm\\\",\\\"skills\\\");skill(managed,\\\"same\\\",\\\"managed\\\");skill(projectSkills,\\\"same\\\",\\\"project\\\");const d=join(projectSkills,\\\"extra\\\");mkdirSync(join(d,\\\"references\\\"),{recursive:true});writeFileSync(join(d,\\\"SKILL.md\\\"),\\\"---\\\\nname: extra\\\\ndescription: extra\\\\n---\\\\nbody\\\");writeFileSync(join(d,\\\"references\\\",\\\"x.txt\\\"),\\\"bytes\\\");const r=new SkillLoader({cwd:project,managedDir:managed,installDir:join(root,\\\"install\\\"),home:root}).load();expect(r.skills.find(s=>s.name===\\\"same\\\")?.instructions).toBe(\\\"managed\\\");expect(r.skills.find(s=>s.name===\\\"extra\\\")?.supportFiles.some(x=>x.endsWith(\\\"x.txt\\\"))).toBe(true);});\\n it(\\\"supports closed allowlists\\\",()=>{const root=mkdtempSync(join(tmpdir(),\\\"skills-\\\"));skill(root,\\\"one\\\",\\\"a\\\");skill(root,\\\"two\\\",\\\"b\\\");const r=new SkillLoader({closed:true,cliPaths:[root],allowedNames:[\\\"two\\\"]}).load();expect(r.skills.map(s=>s.name)).toEqual([\\\"two\\\"]);});\\n it(\\\"emits available_skills metadata without instruction bodies\\\",()=>{const root=mkdtempSync(join(tmpdir(),\\\"skills-\\\"));skill(root,\\\"prompt-skill\\\",\\\"private instructions\\\");const loaded=new SkillLoader({closed:true,cliPaths:[root]}).load().skills;const xml=generateAvailableSkillsXML(loaded);expect(xml).toContain(\\\"<available_skills>\\\");expect(xml).toContain(\\\"<name>prompt-skill</name>\\\");expect(xml).toContain(\\\"<location>\\\");expect(xml).not.toContain(\\\"private instructions\\\");});\\n});\\n\",\"autogenskills/test/index.test.ts\":\"import { describe, expect, it, vi } from \\\"vitest\\\";\\nimport { AutoSkillManager, CuratorOrchestrator, registerAutoSkills } from \\\"../src/index.js\\\";\\nimport { registerAutoSkillsExtension } from \\\"../../.pi/extensions/autogenskills.ts\\\";\\nimport { createHash } from \\\"node:crypto\\\";\\nimport { spawn } from \\\"node:child_process\\\";\\nimport { chmodSync, existsSync, mkdirSync, mkdtempSync, readFileSync, symlinkSync, writeFileSync } from \\\"node:fs\\\";\\nimport { tmpdir } from \\\"node:os\\\";\\nimport { join } from \\\"node:path\\\";\\n\\nconst instructions = \\\"A reusable production procedure. \\\".repeat(8);\\nconst manager = (extra = {}) => new AutoSkillManager({ dir: mkdtempSync(join(tmpdir(), \\\"autogen-\\\")), mode: \\\"auto\\\", ...extra });\\nconst digest = (value: string | Buffer) => createHash(\\\"sha256\\\").update(value).digest(\\\"hex\\\");\\nconst revisionId = (skill: string, parent: string, action: string, files: Record<string, string>) =>\\n  digest(JSON.stringify({ format: 1, skill, parent, action, files }));\\n\\ndescribe(\\\"autogenerated skills\\\", () => {\\n  it(\\\"defaults to safe never mode and validates exact modes\\\", () => {\\n    expect(new AutoSkillManager({ dir: \\\"/tmp/x\\\" }).config.mode).toBe(\\\"never\\\");\\n    expect(new AutoSkillManager({ mode: \\\"auto\\\" }).config.toolCallBudget).toBe(5);\\n    expect(new AutoSkillManager({ mode: \\\"auto\\\" }).config.workingBudget).toBe(90);\\n    expect(() => new AutoSkillManager({ mode: \\\"invalid\\\" as any })).toThrow(/invalid autogen mode/);\\n  });\\n  it(\\\"tracks metrics, revisions, review hooks, and pinning\\\", () => {\\n    const events: any[] = [], m = manager({ reviewHook: e => events.push(e) });\\n    const created: any = m.execute({ action: \\\"create\\\", name: \\\"build-check\\\", description: \\\"Build checks\\\", instructions });\\n    expect(created.revision).toMatch(/^[a-f0-9]{64}$/);\\n    expect(m.execute({ action: \\\"metrics\\\" }).metrics.mutations).toBe(1);\\n    expect(m.execute({ action: \\\"pin\\\", name: \\\"build-check\\\" }).state).toBe(\\\"pinned\\\");\\n    expect(() => m.execute({ action: \\\"archive\\\", name: \\\"build-check\\\" })).toThrow(/pinned/);\\n    expect(events.map(e => e.action)).toEqual([\\\"create\\\", \\\"pin\\\"]);\\n  });\\n  it(\\\"rejects stale mutations until a review and supports expected revisions\\\", () => {\\n    const m = manager({ toolCallBudget: 1 });\\n    m.observeTool(true, \\\"TaskManage\\\", { status: \\\"in_progress\\\", active: true });\\n    m.observeTool(true, \\\"bash\\\");\\n    expect(() => m.execute({ action: \\\"create\\\", name: \\\"too-late\\\", description: \\\"x\\\", instructions })).toThrow(/budget/);\\n  });\\n  it(\\\"rehydrates the complete budget state from Pi session entries\\\", () => {\\n    const entries: any[] = [];\\n    const first = new AutoSkillManager({ dir: mkdtempSync(join(tmpdir(), \\\"autogen-\\\")), mode: \\\"auto\\\" }, (entry: any) => entries.push(entry));\\n    first.observeTool(true, \\\"bash\\\", { command: \\\"node build\\\" });\\n    first.observeTool(false, \\\"write\\\", { path: \\\"x\\\" });\\n    const before = first.snapshot();\\n    const restored = manager();\\n    restored.rehydrate(entries.map(entry => ({\\n      type: \\\"custom\\\",\\n      customType: entry.type,\\n      data: entry.data,\\n    })));\\n    expect(restored.snapshot()).toMatchObject({\\n      toolCalls: before.toolCalls,\\n      budgetCalls: before.budgetCalls,\\n      errors: before.errors,\\n      skilled: before.skilled,\\n      reviewRequired: before.reviewRequired,\\n    });\\n    restored.rehydrate([]);\\n    expect(restored.snapshot()).toEqual(expect.objectContaining({\\n      toolCalls: 0,\\n      budgetCalls: 0,\\n      errors: 0,\\n      reviewRequired: false,\\n    }));\\n  });\\n  it(\\\"hard-blocks onboarding calls and escalates working-tier nudges\\\", () => {\\n    const onboarding = manager({ toolCallBudget: 1 });\\n    onboarding.observeTool(true, \\\"TaskManage\\\", { status: \\\"in_progress\\\", active: true });\\n    onboarding.observeTool(true, \\\"bash\\\");\\n    expect(onboarding.gateTool(\\\"write\\\", { path: \\\"x\\\" })).toMatchObject({ block: true });\\n\\n    const working = manager({ toolCallBudget: 1, workingBudget: 2, maxNudgeIgnores: 2, nudgeInterval: 1, toolCallThreshold: 1 });\\n    working.observeTool(true, \\\"Skill\\\", { skill: \\\"external-skill\\\" });\\n    working.observeTool(true, \\\"write\\\");\\n    working.observeTool(true, \\\"write\\\");\\n    expect(working.observeTurn()).toBeUndefined();\\n    expect(working.observeTurn()).toContain(\\\"Review reusable learning\\\");\\n    expect(working.observeTurn()).toContain(\\\"review required\\\");\\n    expect(working.gateTool(\\\"write\\\")).toMatchObject({ block: true, reason: expect.stringContaining(\\\"review required\\\") });\\n  });\\n\\n  it(\\\"registers no hooks or tools in never mode\\\", () => {\\n    const events: string[] = [], tools: string[] = [];\\n    registerAutoSkills({\\n      appendEntry() {},\\n      on(event: string) { events.push(event); },\\n      registerTool(tool: any) { tools.push(tool.name); },\\n    }, { mode: \\\"never\\\", dir: mkdtempSync(join(tmpdir(), \\\"autogen-\\\")) });\\n    expect(events).toEqual([]);\\n    expect(tools).toEqual([]);\\n  });\\n\\n  it(\\\"appends lifecycle nudges to tool content for model visibility\\\", async () => {\\n    const handlers = new Map<string, Array<(event: any, ctx: any) => unknown>>();\\n    registerAutoSkills({\\n      appendEntry() {},\\n      on(event: string, handler: (event: any, ctx: any) => unknown) {\\n        handlers.set(event, [...(handlers.get(event) ?? []), handler]);\\n      },\\n      registerTool() {},\\n    }, {\\n      mode: \\\"auto\\\",\\n      dir: mkdtempSync(join(tmpdir(), \\\"autogen-\\\")),\\n      nudgeInterval: 1,\\n      toolCallThreshold: 1,\\n    });\\n    const resultHook = handlers.get(\\\"tool_result\\\")![0];\\n    await resultHook({ toolName: \\\"read\\\", content: [{ type: \\\"text\\\", text: \\\"first\\\" }] }, {});\\n    const result: any = await resultHook({ toolName: \\\"read\\\", content: [{ type: \\\"text\\\", text: \\\"second\\\" }] }, {});\\n    expect(result.content[0].text).toBe(\\\"second\\\");\\n    expect(result.content.at(-1).text).toContain(\\\"Review reusable learning\\\");\\n  });\\n\\n  it(\\\"charges every Bash command at tool_call time, including read-only commands\\\", () => {\\n    const m = manager({ toolCallBudget: 10 });\\n    m.observeTool(true, \\\"TaskManage\\\", { operations: [{ status: \\\"in_progress\\\", active: true }] });\\n    m.observeToolAttempt(\\\"bash\\\", { command: \\\"pwd\\\" }, \\\"bash-1\\\");\\n    m.observeToolAttempt(\\\"bash\\\", { command: \\\"ls\\\" }, \\\"bash-2\\\");\\n    m.observeToolAttempt(\\\"bash\\\", { command: \\\"rg pattern file\\\" }, \\\"bash-3\\\");\\n    expect(m.budgetStatus().used).toBe(3);\\n    // A duplicate terminal notification is a result observation, not another\\n    // budget attempt, and a failed command remains charged.\\n    m.observeTool(false, \\\"bash\\\", { command: \\\"false\\\" }, \\\"bash-3\\\");\\n    expect(m.budgetStatus().used).toBe(3);\\n  });\\n\\n  it(\\\"separates one turn from multiple tool results\\\", () => {\\n    const m = manager({ nudgeInterval: 1, toolCallThreshold: 1 });\\n    m.observeTurn();\\n    m.observeTool(true, \\\"bash\\\", { command: \\\"pwd\\\" }, \\\"call-1\\\");\\n    m.observeTool(true, \\\"bash\\\", { command: \\\"ls\\\" }, \\\"call-2\\\");\\n    m.observeTurn();\\n    expect(m.metrics().turns).toBe(2);\\n    expect(m.metrics().toolCalls).toBe(2);\\n  });\\n\\n  it(\\\"renders a theme-colored progress widget matching the TUI conventions\\\", () => {\\n    const m = manager({ toolCallBudget: 4 });\\n    m.observeTool(true, \\\"TaskManage\\\", { operations: [{ status: \\\"in_progress\\\", active: true }] });\\n    m.observeToolAttempt(\\\"bash\\\", {}, \\\"budget-call\\\");\\n    const calls: string[] = [];\\n    const widget: any = m.budgetWidget({}, { fg: (color: string, text: string) => { calls.push(color); return `<${color}>${text}</${color}>`; }, dim: (text: string) => `<dim>${text}</dim>` });\\n    const line = widget.render(80)[0];\\n    expect(line).toContain(\\\"Autogen\\\");\\n    expect(line).toContain(\\\"1/4\\\");\\n    expect(line).toContain(\\\"<accent>█\\\");\\n    expect(line).toContain(\\\"<dim>░\\\");\\n    expect(calls).toContain(\\\"accent\\\");\\n    expect(calls).toContain(\\\"warning\\\");\\n  });\\n\\n  it(\\\"emits an upstream-style skill-review nudge from post-tool activity\\\", () => {\\n    const m = manager({ nudgeInterval: 2 });\\n    m.observeTool(true, \\\"TaskManage\\\", { operations: [{ status: \\\"in_progress\\\", active: true }] });\\n    m.observeTool(true, \\\"custom_tool\\\", {}, \\\"nudge-1\\\");\\n    m.observeTool(true, \\\"custom_tool\\\", {}, \\\"nudge-2\\\");\\n    const nudge = m.observeTool(true, \\\"custom_tool\\\", {}, \\\"nudge-3\\\");\\n    expect(nudge).toContain(\\\"[SKILL REVIEW]\\\");\\n    expect(nudge).toContain(\\\"patch a loaded skill\\\");\\n    expect(nudge).toContain(\\\"no-mutation review\\\");\\n  });\\n\\n  it(\\\"uses Pi tool_result input to activate focused-task budget accounting\\\", async () => {\\n    const handlers = new Map<string, Array<(event: any, ctx: any) => unknown>>();\\n    const m = registerAutoSkills({\\n      appendEntry() {},\\n      on(event: string, handler: (event: any, ctx: any) => unknown) {\\n        handlers.set(event, [...(handlers.get(event) ?? []), handler]);\\n      },\\n      registerTool() {},\\n    }, {\\n      mode: \\\"auto\\\",\\n      dir: mkdtempSync(join(tmpdir(), \\\"autogen-\\\")),\\n    });\\n    const resultHook = handlers.get(\\\"tool_result\\\")![0];\\n    await resultHook({\\n      toolName: \\\"TaskManage\\\",\\n      input: { operations: [{ key: \\\"focus\\\", op: \\\"update\\\", status: \\\"in_progress\\\", active: true }] },\\n      content: [],\\n      isError: false,\\n    }, {});\\n    await resultHook({ toolName: \\\"write\\\", input: { path: \\\"x\\\" }, content: [], isError: true }, {});\\n    expect(m.budgetStatus().used).toBe(1);\\n    expect(m.metrics().errors).toBe(1);\\n  });\\n\\n  it(\\\"absorbs support files byte-for-byte and guards archival provenance\\\", () => {\\n    const m = manager();\\n    const source: any = m.execute({ action: \\\"create\\\", name: \\\"source-skill\\\", description: \\\"Source\\\", instructions });\\n    const target: any = m.execute({ action: \\\"create\\\", name: \\\"target-skill\\\", description: \\\"Target\\\", instructions });\\n    const written: any = m.execute({ action: \\\"write_file\\\", name: \\\"source-skill\\\", file_path: \\\"assets/data.bin\\\", file_content: \\\"\\\\u0000binary\\\\u00ff\\\", expected_revision: source.revision });\\n    expect(() => m.execute({ action: \\\"archive\\\", name: \\\"source-skill\\\", expected_revision: written.revision, absorbed_into: \\\"target-skill\\\" })).toThrow(/absorb_files/);\\n    const absorbed: any = m.execute({ action: \\\"absorb_files\\\", name: \\\"target-skill\\\", from_skill: \\\"source-skill\\\", expected_revision: target.revision });\\n    expect(absorbed.files).toEqual([\\\"assets/data.bin\\\"]);\\n    const archived: any = m.execute({ action: \\\"archive\\\", name: \\\"source-skill\\\", expected_revision: written.revision, absorbed_into: \\\"target-skill\\\" });\\n    expect(archived.absorbed_into).toBe(\\\"target-skill\\\");\\n  });\\n\\n  it(\\\"undo requires the exact head and removes files absent from the target revision\\\", () => {\\n    const m = manager();\\n    const created: any = m.execute({ action: \\\"create\\\", name: \\\"undo-skill\\\", description: \\\"Undo\\\", instructions });\\n    const first: any = m.execute({ action: \\\"write_file\\\", name: \\\"undo-skill\\\", file_path: \\\"references/one.txt\\\", file_content: \\\"one\\\", expected_revision: created.revision });\\n    const second: any = m.execute({ action: \\\"write_file\\\", name: \\\"undo-skill\\\", file_path: \\\"references/two.txt\\\", file_content: \\\"two\\\", expected_revision: first.revision });\\n    expect(() => m.execute({ action: \\\"undo\\\", name: \\\"undo-skill\\\", revision: created.revision, expected_revision: \\\"1.0.0\\\" })).toThrow(/expected_revision/);\\n    m.execute({ action: \\\"undo\\\", name: \\\"undo-skill\\\", revision: created.revision, expected_revision: second.revision });\\n    expect(existsSync(join(m.config.dir, \\\"undo-skill\\\", \\\"references\\\", \\\"one.txt\\\"))).toBe(false);\\n    expect(existsSync(join(m.config.dir, \\\"undo-skill\\\", \\\"references\\\", \\\"two.txt\\\"))).toBe(false);\\n  });\\n\\n  it(\\\"rolls an undo swap back when revert revision publication fails\\\", () => {\\n    const m = manager();\\n    const created: any = m.execute({ action: \\\"create\\\", name: \\\"undo-rollback\\\", description: \\\"Undo\\\", instructions });\\n    const current: any = m.execute({\\n      action: \\\"write_file\\\",\\n      name: \\\"undo-rollback\\\",\\n      file_path: \\\"references/current.txt\\\",\\n      file_content: \\\"current\\\",\\n      expected_revision: created.revision,\\n    });\\n    const createdManifest = JSON.parse(readFileSync(join(\\n      m.config.dir, \\\".history\\\", \\\"revisions\\\", \\\"undo-rollback\\\", `${created.revision}.json`,\\n    ), \\\"utf8\\\"));\\n    const future = revisionId(\\\"undo-rollback\\\", current.revision, \\\"undo\\\", createdManifest.files);\\n    writeFileSync(join(m.config.dir, \\\".history\\\", \\\"revisions\\\", \\\"undo-rollback\\\", `${future}.json`), [result truncated: 165352 bytes exceeds the 131072-byte output limit; return a smaller value]",
