  const path = promptStorePath(cwd);
  // Preserve the original Pi-Swarm default: Forge owns the prompt until the
  // user explicitly selects Pi's base prompt.
  if (!existsSync(path)) return { prompts: [], active: FORGE_PROMPT };
  try {
